vt=[];vte=[];
vt[vt.length]=`<div id="text_88" class="textshirt mergershirt" style="top: 43px; left: 404px; font-size: 26px;"></div>`;
vt[vt.length]=`<div id="text_89" class="textshirt mergershirt" style="word-break: break-word; width: 336px; white-space: normal; top: 47px; left: 406px; height: 360px; font-size: 13px;">Je soupirai, le son absorbé par la pièce silencieuse. «&nbsp;Demain, cerveau&nbsp;», déclarai-je à l’obscurité, «&nbsp;Nous nous attaquerons au monde du commerce. Ou peut-être juste trouver comment faire des toasts. Pour l’instant, on va juste... pas." Je me suis retournée, remontant la couette jusqu’à mon menton, et j’ai laissé jouer la symphonie chaotique de mes décisions non prises jusqu’à ce que la première lueur grise traverse les stores.</div>`;
vt[vt.length]=`<div id="text_90" class="textshirt mergershirt" style="width: 335px; white-space: normal; top: 46px; left: 786px; height: 360px;"></div>`;



vte[vte.length]=`<div id="text_88" class="textshirt mergershirt`+transws+`" style="top: 43px; left: 404px; font-size: 26px;"></div>`;
vte[vte.length]=`<div id="text_89" class="textshirt mergershirt`+transws+`" style="word-break: break-word; width: 336px; white-space: normal; top: 47px; left: 406px; height: 360px; font-size: 13px;">I sighed, the sound swallowed by the quiet room. "Tomorrow, brain," I declared to the darkness, "We'll tackle the world of commerce. Or maybe just figure out how to make toast. For now, let's just… not." I rolled over, pulling the duvet up to my chin, and let the chaotic symphony of my unmade decisions play on until the first hint of grey light crept through the blinds.</div>`;
vte[vte.length]=`<div id="text_90" class="textshirt mergershirt`+transws+`" style="width: 335px; white-space: normal; top: 46px; left: 786px; height: 360px;"></div>`;


